```
function jsonToTable(json) {
  var table = "<table>";
  for (var i = 0; i < json.length; i++) {
    var row = "<tr>";
    for (var key in json[i]) {
      row += "<td>" + json[i][key] + "</td>";
    }
    table += row + "</tr>";
  }
  table += "</table>";
  return table;
}
```
